/**
 * SalinTayo TTS wrapper.
 *
 * Providers:
 *
 * 1. Camb.AI
 *    - Existing female voice/provider.
 *    - Kept intact as the default female voice.
 *
 * 2. Edge TTS
 *    - Used for Angelo male voice.
 *    - Voice: fil-PH-AngeloNeural
 *    - Audio is generated by a backend using edge-tts.
 *
 * 3. Native Capacitor TTS
 *    - Fallback when Camb.AI fails or is unavailable.
 *
 * 4. Browser SpeechSynthesis
 *    - Final fallback on web.
 *
 * Existing callers continue using:
 *   speakText(text, options)
 *   cancelSpeech()
 *
 * Voice preference:
 *   salintayo_tts_voice
 *
 * Supported values:
 *   camb-female
 *   angelo-male
 */

import { Capacitor } from '@capacitor/core';
import {
  QueueStrategy,
  TextToSpeech,
} from '@capacitor-community/text-to-speech';

import { logBootStep } from './bootLogger';
import { getResolvedDialectLangCode, QCB_DIALECT_LANG_STORAGE_KEY, DIALECT_LANG_STORAGE_KEY } from './dialectPreference';

type DialectCode = string;

/* =========================================================
   PROVIDER / VOICE SETTINGS
   ========================================================= */

export type TtsVoiceId = 'camb-female' | 'angelo-male';

export const TTS_VOICE_STORAGE_KEY = 'salintayo_tts_voice';

export const DEFAULT_TTS_VOICE: TtsVoiceId = 'camb-female';

const CAMB_API_KEY =
  (import.meta.env.VITE_CAMB_API_KEY as string | undefined) ?? '';

const CAMB_TTS_VOICE_ID =
  Number(import.meta.env.VITE_CAMB_TTS_VOICE_ID ?? '') || 170787;

const CAMB_TTS_URL =
  'https://client.camb.ai/apis/tts-stream';

/**
 * Backend endpoint for Edge TTS.
 *
 * The backend should:
 *
 * POST JSON:
 * {
 *   "text": "...",
 *   "voice": "fil-PH-AngeloNeural"
 * }
 *
 * and return audio bytes.
 */
const EDGE_TTS_URL =
  (import.meta.env.VITE_EDGE_TTS_URL as string | undefined) ?? '';

const EDGE_TTS_VOICE =
  'fil-PH-AngeloNeural';

/* =========================================================
   VOICE PREFERENCE
   ========================================================= */

/**
 * Get the currently selected TTS voice.
 *
 * This is intentionally stored in localStorage so Profile,
 * Chat, Emergency Bubble, Quick Chat, and Auto-Mic can all
 * share one setting.
 */
export function getSelectedTtsVoice(): TtsVoiceId {
  try {
    const saved = localStorage.getItem(TTS_VOICE_STORAGE_KEY);

    if (saved === 'angelo-male') {
      return 'angelo-male';
    }

    if (saved === 'camb-female') {
      return 'camb-female';
    }
  } catch {
    // Ignore localStorage errors.
  }

  return DEFAULT_TTS_VOICE;
}

/**
 * Save the selected TTS voice.
 *
 * A custom event is emitted so currently-mounted components
 * can react immediately without requiring a page reload.
 */
export function setSelectedTtsVoice(voice: TtsVoiceId): void {
  try {
    localStorage.setItem(TTS_VOICE_STORAGE_KEY, voice);

    window.dispatchEvent(
      new CustomEvent('salintayo_tts_voice_changed', {
        detail: { voice },
      }),
    );
  } catch {
    // Ignore localStorage errors.
  }
}

/**
 * Human-readable labels for Profile/settings UI.
 */
export function getTtsVoiceLabel(voice: TtsVoiceId): string {
  switch (voice) {
    case 'angelo-male':
      return 'Angelo — Filipino Male';

    case 'camb-female':
    default:
      return 'Camb.AI — Female';
  }
}

