const LANG_LOCALE_MAP: Record<string, string> = {
  en: 'en-US',
  fil: 'fil-PH',
  ceb: 'ceb-PH',
  ilo: 'ilo-PH',
  hil: 'hil-PH',
  war: 'war-PH',
  bik: 'bik-PH',
  pam: 'pam-PH',
  pag: 'pag-PH',
  tsg: 'tsg-PH',
};

function getDialectCodeForTts(): DialectCode {
  try {
    const code =
      localStorage.getItem(QCB_DIALECT_LANG_STORAGE_KEY) ??
      localStorage.getItem(DIALECT_LANG_STORAGE_KEY) ??
      getResolvedDialectLangCode();

    return (code || '').trim().toLowerCase() || 'en';
  } catch {
    return 'en';
  }
}

export function getTtsLocale(): string {
  // Legacy name retained for existing callers.
  const code = getDialectCodeForTts();

  return LANG_LOCALE_MAP[code] ?? 'en-US';
}

/* =========================================================
   DIALECT PRONUNCIATION RULES
   ========================================================= */

interface DialectRule {
  pattern: string;
  replacement: string;
}

const DIALECT_RULES: Record<string, DialectRule[]> = {
  // Avoid aggressive pronunciation hacks.
  // These rules are kept exactly conservative.
  fil: [],

  ceb: [],

  ilo: [],

  hil: [
    {
      pattern: '\\bnakaon ka na\\b',
      replacement: 'na-kaon ka na',
    },
    {
      pattern: '\\bnakaon ka\\b',
      replacement: 'na-kaon ka',
    },
    {
      pattern: '\\bnakaon\\b',
      replacement: 'na-kaon',
    },
    {
      pattern: '\\bkaon\\b',
      replacement: 'ka-on',
    },
    {
      pattern: '\\bpa ka\\b',
      replacement: 'pa ka',
    },
    {
      pattern: '\\bna ka na\\b',
      replacement: 'naka na',
    },
    {
      pattern: '\\bnakayon\\b',
      replacement: 'nakaon',
    },
    {
      pattern: '\\bpatay\\b',
      replacement: 'pati',
    },
  ],

  pag: [],

  en: [],
};

function getDialectRules(code: string): DialectRule[] {
  const normalized = (code || '').trim().toLowerCase();

  return DIALECT_RULES[normalized] ?? DIALECT_RULES.fil;
}

function applyDialectTransform(
  text: string,
  rules: DialectRule[],
): string {
  return rules.reduce((current, rule) => {
    try {
      return current.replace(
        new RegExp(rule.pattern, 'gi'),
        rule.replacement,
      );
    } catch {
      return current;
    }
  }, text);
}

